     9	  let error: string | undefined;
    10	  for (const recording of recordings) {
    11	    signal?.throwIfAborted();
    12	    if (analyses.some(analysis => analysis.recordingId === recording.id)) continue;
    13	    try {
    14	      const response = await fetch('/api/analyse-audio', { method: 'POST', headers: { 'Content-Type': 'audio/wav' }, body: recording.blob, signal });
    15	      const body = await response.json();
