     2	export function mergeAudioChunks(chunks: readonly Float32Array[], maxSamples: number): Float32Array {
     3	  const total = Math.min(maxSamples, chunks.reduce((length, chunk) => length + chunk.length, 0));
     4	  const samples = new Float32Array(total);
     5	  let offset = 0;
     6	  for (const chunk of chunks) {
     7	    const remaining = total - offset;
     8	    if (remaining <= 0) break;
     9	    const included = chunk.subarray(0, remaining);
    10	    samples.set(included, offset);
    11	    offset += included.length;
    12	  }
    13	  return samples;
