    17	export function resampleMono(samples: Float32Array, sourceRate: number, targetRate: number): Float32Array {
    18	  if (!Number.isInteger(sourceRate) || !Number.isInteger(targetRate) || targetRate < 1 || sourceRate < targetRate) {
    19	    throw new Error("Invalid audio sample rate.");
    20	  }
    21	  if (sourceRate === targetRate) return samples.slice();
    22	  const ratio = sourceRate / targetRate;
    23	  return Float32Array.from({ length: Math.floor(samples.length / ratio) }, (_, index) => {
    24	    const start = index * ratio;
