     6	export const MAX_AUDIO_CLIP_BYTES = 44 + 60 * 16000 * 2;
     7	/** Recordings are made by our PCM encoder; accept only that bounded, canonical format. */
     8	export function audioClipDuration(bytes: Uint8Array) {
     9	    const invalid = () => new ApiError(400, 'Send a PCM16 mono WAV recording at 16 kHz, up to 60 seconds.');
    10	    if (bytes.length <= 44 || bytes.length > MAX_AUDIO_CLIP_BYTES || (bytes.length - 44) % 2) throw invalid();
    11	    const view = new DataView(bytes.buffer, bytes.byteOffset, bytes.byteLength);
    12	    const text = (offset: number, count: number) => new TextDecoder().decode(bytes.subarray(offset, offset + count));
    13	    if (text(0, 4) !== 'RIFF' || view.getUint32(4, true) !== bytes.length - 8 || text(8, 8) !== 'WAVEfmt '
    14	        || view.getUint32(16, true) !== 16 || view.getUint16(20, true) !== 1 || view.getUint16(22, true) !== 1
    15	        || view.getUint32(24, true) !== 16000 || view.getUint32(28, true) !== 32000 || view.getUint16(32, true) !== 2
    16	        || view.getUint16(34, true) !== 16 || text(36, 4) !== 'data' || view.getUint32(40, true) !== bytes.length - 44) throw invalid();
    17	    return (bytes.length - 44) / 32000;
    18	}
    19	const wordSchema = z.object({
    20	    type: z.literal('word_info'), text: z.string().min(1).max(200),
    21	    start_offset: z.string().regex(/^\d+(?:\.\d+)?s$/), end_offset: z.string().regex(/^\d+(?:\.\d+)?s$/),
    22	});
    23	const outputSchema = z.object({
    24	    status: z.literal('completed'),
    25	    steps: z.array(z.object({ type: z.literal('model_output'), content: z.array(z.object({
    26	        type: z.literal('text'), text: z.string().max(24000), annotations: z.array(wordSchema).max(6000).default([]),
    27	    })).max(20) })).max(20),
    28	});
    29	export function parseAudioAnalysis(output: unknown, model: string, durationSeconds: number): AudioAnalysisResponse {
    30	    const parsed = outputSchema.parse(output);
    31	    const parts = parsed.steps.flatMap(step => step.content);
    32	    const words = parts.flatMap(part => part.annotations).map(word => ({
    33	        word: word.text, startSeconds: Number(word.start_offset.slice(0, -1)), endSeconds: Number(word.end_offset.slice(0, -1)),
    34	    }));
    35	    if (parts.some(part => part.text.trim() && !part.annotations.length)
    36	        || words.some((word, index) => word.startSeconds < 0 || word.endSeconds <= word.startSeconds || word.endSeconds > durationSeconds
    37	            || (index > 0 && word.startSeconds < words[index - 1].endSeconds))) {
    38	        throw new Error('Transcription has missing or invalid word timestamps.');
    39	    }
    40	    return audioAnalysisResponseSchema.parse({ model, transcript: parts.map(part => part.text).join('\n'), fillers: words.filter(word => isHesitation(word.word)) });
    41	}
    42	export async function analyseAudio(bytes: Uint8Array) {
    43	    const duration = audioClipDuration(bytes);
    44	    const client = new GoogleGenAI({ apiKey: requireKey('GEMINI_API_KEY') });
    45	    const model = process.env.GEMINI_AUDIO_MODEL || 'gemini-3.5-transcribe';
    46	    // Dedicated ASR treats speech as audio to transcribe, never as agent instructions.
    47	    // Inline data and store:false avoid creating a remotely retrievable recording/interaction.
    48	    const output = await client.interactions.create({
    49	        model, store: false,
    50	        input: [{ type: 'audio', mime_type: 'audio/wav', data: Buffer.from(bytes).toString('base64') }],
    51	        generation_config: { transcription_config: { mode: { type: 'verbatim', timestamp_granularities: ['word'] } } },
    52	    }, { timeout_ms: 90000, signal: AbortSignal.timeout(90000) });
    53	    try { return parseAudioAnalysis(output, model, duration); }
    54	    catch {
    55	        throw new ApiError(502, 'Gemini could not provide valid audio timestamps. Your recording is still available for playback.');
    56	    }
    57	}

