     5	export async function analyseSessionAudio(recordings: AudioRecording[], previous: AudioClipAnalysis[] = [], signal?: AbortSignal): Promise<AudioReview> {
     6	  signal?.throwIfAborted();
     7	  const metadata = recordings.map(({ id, durationSeconds }) => ({ id, durationSeconds }));
     8	  let analyses = previous.filter(analysis => metadata.some(recording => recording.id === analysis.recordingId));
     9	  let error: string | undefined;
    10	  for (const recording of recordings) {
