    17	      const parsed = audioAnalysisResponseSchema.parse(body);
    18	      const next = [...analyses, { ...parsed, recordingId: recording.id }];
    19	      audioReviewSchema.parse({ recordings: metadata, analyses: next });
    20	      analyses = next;
    21	    } catch (cause) {
    22	      signal?.throwIfAborted();
